//! The trust anchors of the TLS client written in Velt (`std/net/tls/x509/roots_table.velt`,
//! generated by `scripts/gen-tls-roots.py`) are the ones rustls uses here: `webpki-roots`'
//! `TLS_SERVER_ROOTS`, one by one and byte for byte. A Velt program then trusts the same roots
//! through either stack. When this fails after a `webpki-roots` update, run the script again.

use std::path::Path;

/// The numbers of the array literal `name` in `text`.
fn array(text: &str, name: &str) -> Vec<u64> {
    let start = text
        .find(&format!("export const {name}:"))
        .unwrap_or_else(|| panic!("no {name} in the table"));
    let body = &text[start..];
    let open = body.find('[').expect("the array's type") + 1;
    let open = open + body[open..].find('[').expect("the array's start") + 1;
    let close = open + body[open..].find(']').expect("the array's end");
    body[open..close]
        .split(',')
        .map(str::trim)
        .filter(|n| !n.is_empty())
        .map(|n| match n.strip_prefix("0x") {
            Some(hex) => u64::from_str_radix(hex, 16).expect("a hex number"),
            None => n.parse().expect("a number"),
        })
        .collect()
}

#[test]
fn the_velt_table_is_webpki_roots() {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../std/net/tls/x509/roots_table.velt");
    let text = std::fs::read_to_string(&path).expect("the table");
    let bytes: Vec<u8> = array(&text, "ROOT_BYTES")
        .iter()
        .flat_map(|w| w.to_le_bytes())
        .collect();
    let ends = array(&text, "ROOT_ENDS");
    let roots = webpki_roots::TLS_SERVER_ROOTS;
    assert_eq!(ends.len(), 3 * roots.len(), "the number of anchors");
    let mut at = 0usize;
    for (i, root) in roots.iter().enumerate() {
        let part = |end: u64, at: &mut usize| {
            let slice = &bytes[*at..end as usize];
            *at = end as usize;
            slice
        };
        assert_eq!(
            part(ends[3 * i], &mut at),
            root.subject.as_ref(),
            "subject of anchor {i}"
        );
        assert_eq!(
            part(ends[3 * i + 1], &mut at),
            root.subject_public_key_info.as_ref(),
            "key of anchor {i}"
        );
        let constraints = root
            .name_constraints
            .as_ref()
            .map_or(&[][..], |c| c.as_ref());
        assert_eq!(
            part(ends[3 * i + 2], &mut at),
            constraints,
            "name constraints of anchor {i}"
        );
    }
    assert!(
        bytes[at..].iter().all(|b| *b == 0),
        "only padding after the last anchor"
    );
}
